package com.chronos.education.grade.controller;
import com.chronos.commons.model.ResultData; import com.chronos.education.grade.model.CourseGrade; import com.chronos.education.grade.service.GradeCenterService; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/portal/education/grades") public class GradePortalController { private final GradeCenterService service; public GradePortalController(GradeCenterService service){this.service=service;} @GetMapping public ResultData<List<CourseGrade>> list(Authentication a){return ResultData.<List<CourseGrade>>builder().code("200").msg("ok").data(service.studentGrades(a.getName())).build();} @GetMapping("/{id}") public ResultData<CourseGrade> detail(@PathVariable String id,Authentication a){return ResultData.<CourseGrade>builder().code("200").msg("ok").data(service.studentGrade(id,a.getName())).build();} }
